<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $order_id
 * @property string $listing_id
 * @property string $title
 * @property string $listing_slug
 * @property string|null $image_media_id
 * @property string|null $condition
 * @property string $format
 * @property string|null $size
 * @property bool $size_from_fit_kit
 * @property int $quantity
 * @property int $unit_price
 * @property int $total
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class OrderItem extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'oi';

    protected $fillable = [
        'order_id', 'listing_id', 'title', 'listing_slug', 'image_media_id', 'condition', 'format', 'size',
        'size_from_fit_kit', 'quantity', 'unit_price', 'total',
    ];

    protected function casts(): array
    {
        return [
            'size_from_fit_kit' => 'boolean',
        ];
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }

    /** @return BelongsTo<Listing, $this> */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(Listing::class);
    }

    /** @return BelongsTo<Media, $this> */
    public function image(): BelongsTo
    {
        return $this->belongsTo(Media::class, 'image_media_id');
    }
}
